import { render } from '@solidjs/web';
import { createSignal, Show } from 'solid-js';
import clickOutside from './click-outside';
import './style.css';

function Modal(props) {
  const outside = clickOutside(() => props.close());
  return (
    <div class="modal" ref={outside}>
      Click anywhere outside to close.
    </div>
  );
}

function App() {
  const [show, setShow] = createSignal(false);
  return (
    <>
      <button onClick={() => setShow(true)}>Open modal</button>
      <Show when={show()}>
        <Modal close={() => setShow(false)} />
      </Show>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

import { onSettled } from 'solid-js';

export default function clickOutside(close) {
  let element;
  // Listen for pointerdown on the document and call close() when the
  // target is outside element. Return cleanup that removes the listener.

  return (el) => (element = el);
}

import { render } from '@solidjs/web';
import { createSignal, Show } from 'solid-js';
import clickOutside from './click-outside';
import './style.css';

function Modal(props) {
  const outside = clickOutside(() => props.close());
  return (
    <div class="modal" ref={outside}>
      Click anywhere outside to close.
    </div>
  );
}

function App() {
  const [show, setShow] = createSignal(false);
  return (
    <>
      <button onClick={() => setShow(true)}>Open modal</button>
      <Show when={show()}>
        <Modal close={() => setShow(false)} />
      </Show>
